#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAXN 205
#define MAXM 20005
#define INF 1000000000

typedef struct {
    int v, w;
} Edge;

Edge edges[MAXM];
int head[MAXN], nxt[MAXM], edge_cnt;
int N, M, T;
int p[MAXN], t[MAXN], k[MAXN];
int dp[MAXN][MAXN][2]; // dp[node][time][watched_flag]

void add_edge(int u, int v, int w) {
    edges[edge_cnt].v = v;
    edges[edge_cnt].w = w;
    nxt[edge_cnt] = head[u];
    head[u] = edge_cnt++;
}

int min(int a, int b) { return a < b ? a : b; }
int max(int a, int b) { return a > b ? a : b; }

int main() {
    scanf("%d %d %d", &N, &M, &T);
    for (int i = 1; i <= N; i++) {
        scanf("%d %d %d", &p[i], &t[i], &k[i]);
    }
    memset(head, -1, sizeof(head));
    edge_cnt = 0;
    for (int i = 0; i < M; i++) {
        int u, v, w;
        scanf("%d %d %d", &u, &v, &w);
        add_edge(u, v, w);
        add_edge(v, u, w);
    }

    // Initialize dp with -INF
    for (int i = 0; i <= N; i++)
        for (int j = 0; j <= T; j++)
            for (int f = 0; f < 2; f++)
                dp[i][j][f] = -INF;

    // Start from any node, can watch or not
    for (int i = 1; i <= N; i++) {
        if (t[i] <= T && k[i] > 0) {
            dp[i][t[i]][1] = max(dp[i][t[i]][1], p[i]);
        }
        dp[i][0][0] = max(dp[i][0][0], 0);
    }

    int ans = 0;

    // Bellman-Ford style DP over time
    for (int time = 0; time <= T; time++) {
        for (int u = 1; u <= N; u++) {
            for (int f = 0; f < 2; f++) {
                if (dp[u][time][f] < 0) continue;
                ans = max(ans, dp[u][time][f]);

                // Option: stay and watch (if not watched yet on this visit)
                if (f == 0 && time + t[u] <= T && k[u] > 0) {
                    dp[u][time + t[u]][1] = max(dp[u][time + t[u]][1], dp[u][time][0] + p[u]);
                }

                // Move to neighbor
                for (int e = head[u]; e != -1; e = nxt[e]) {
                    int v = edges[e].v;
                    int w = edges[e].w;
                    if (time + w <= T) {
                        // After moving, reset watch flag
                        dp[v][time + w][0] = max(dp[v][time + w][0], dp[u][time][f]);
                    }
                }
            }
        }
    }

    printf("%d\n", ans);
    return 0;
}

