int parent[105];
int find(int x) { return parent[x] == x ? x : (parent[x] = find(parent[x])); }
void unite(int a, int b) { parent[find(a)] = find(b); }

int dp[10005];

int main() {
    int N, M, T;
    scanf("%d %d %d", &N, &M, &T);

    int p[105], t[105], k[105];
    for (int i = 1; i <= N; i++) scanf("%d %d %d", &p[i], &t[i], &k[i]);

    for (int i = 1; i <= N; i++) parent[i] = i;
    for (int i = 0; i < M; i++) {
        int u, v; scanf("%d %d", &u, &v);
        unite(u, v);
    }

    // For each component, solve knapsack
    int ans = 0;
    // Try each node as representative
    for (int rep = 1; rep <= N; rep++) {
        if (find(rep) != rep) continue;
        memset(dp, 0, sizeof(dp));
        for (int i = 1; i <= N; i++) {
            if (find(i) != rep) continue;
            // Add item i with multiplicity k[i], weight t[i], value p[i]
            // Binary grouping
            int rem = k[i];
            for (int b = 1; rem > 0; b *= 2) {
                int cnt = (b < rem) ? b : rem;
                rem -= cnt;
                int wt = cnt * t[i], vl = cnt * p[i];
                for (int j = T; j >= wt; j--)
                    if (dp[j-wt] + vl > dp[j]) dp[j] = dp[j-wt] + vl;
            }
        }
        for (int j = 0; j <= T; j++) if (dp[j] > ans) ans = dp[j];
    }
    printf("%d\n", ans);
    return 0;
}

#include <stdio.h>
