typedef long long ll;

#define NEG_INF (-(1LL<<60))

typedef struct {
    int to, next;
} Edge;

static int cmp_ll_desc(const void *a, const void *b) {
    ll x = *(const ll*)a;
    ll y = *(const ll*)b;
    if (x < y) return 1;
    if (x > y) return -1;
    return 0;
}

int main(void) {
    int N, M, T;
    if (scanf("%d %d %d", &N, &M, &T) != 3) return 0;

    int *p = (int*)malloc((N + 1) * sizeof(int));
    int *tt = (int*)malloc((N + 1) * sizeof(int));
    int *k = (int*)malloc((N + 1) * sizeof(int));

    for (int i = 1; i <= N; i++) {
        scanf("%d %d %d", &p[i], &tt[i], &k[i]);
    }

    Edge *edges = (Edge*)malloc((2 * M) * sizeof(Edge));
    int *head = (int*)malloc((N + 1) * sizeof(int));
    for (int i = 1; i <= N; i++) head[i] = -1;

    int ecnt = 0;
    for (int i = 0; i < M; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        edges[ecnt].to = b; edges[ecnt].next = head[a]; head[a] = ecnt++;
        edges[ecnt].to = a; edges[ecnt].next = head[b]; head[b] = ecnt++;
    }

    /* If there is no link, you cannot rewatch after first watch at a site.
       Since you can start anywhere and end anywhere, answer is max single watch. */
    if (M == 0) {
        ll ans = 0;
        for (int i = 1; i <= N; i++) {
            if (tt[i] <= T && k[i] > 0 && p[i] > ans) ans = p[i];
        }
        printf("%lld\n", ans);
        free(p); free(tt); free(k); free(edges); free(head);
        return 0;
    }

    /*
      Key observation:
      Since graph is undirected, inside any connected component with at least one edge,
      we can traverse edges arbitrarily many times and revisit vertices.
      The only restriction is: between two watches of the same site's ad, at least one link
      must be used. This is always feasible in such a component if there is at least one edge.
      Therefore each ad i in a nontrivial component behaves like an item usable up to k_i times,
      each use costs t_i seconds and gives p_i points.
      Starting/ending anywhere means no extra movement cost matters beyond existence of some edge
      to separate repeated watches. Because link traversal time is not specified, it is zero.
      We can choose one connected component with at least one edge and solve bounded knapsack over
      all vertices in that component. Also isolated vertices allow only one watch (if k_i>=1).
    */

    int *vis = (int*)calloc(N + 1, sizeof(int));
    int *queue = (int*)malloc((N + 5) * sizeof(int));
    ll answer = 0;

    ll *dp = (ll*)malloc((T + 1) * sizeof(ll));
    ll *ndp = (ll*)malloc((T + 1) * sizeof(ll));

    for (int s = 1; s <= N; s++) {
        if (vis[s]) continue;

        /* BFS component */
        int qh = 0, qt = 0;
        queue[qt++] = s;
        vis[s] = 1;

        int *verts = (int*)malloc((N + 1) * sizeof(int));
        int vcnt = 0;
        int hasEdge = 0;

        while (qh < qt) {
            int u = queue[qh++];
            verts[vcnt++] = u;
            if (head[u] != -1) hasEdge = 1;
            for (int e = head[u]; e != -1; e = edges[e].next) {
                int v = edges[e].to;
                if (!vis[v]) {
                    vis[v] = 1;
                    queue[qt++] = v;
                }
            }
        }

        if (!hasEdge) {
            int i = verts[0];
            if (k[i] > 0 && tt[i] <= T && p[i] > answer) answer = p[i];
            free(verts);
            continue;
        }

        for (int t = 0; t <= T; t++) dp[t] = NEG_INF;
        dp[0] = 0;

        for (int idx = 0; idx < vcnt; idx++) {
            int i = verts[idx];
            if (k[i] <= 0 || tt[i] > T) continue;

            int maxc = k[i];
            int cost = tt[i];
            int val = p[i];

            /* Bounded knapsack by binary splitting */
            int take = 1;
            while (maxc > 0) {
                int cnt = (take < maxc ? take : maxc);
                int w = cnt * cost;
                ll gain = (ll)cnt * val;
                for (int t = T; t >= w; t--) {
                    if (dp[t - w] != NEG_INF) {
                        ll cand = dp[t - w] + gain;
                        if (cand > dp[t]) dp[t] = cand;
                    }
                }
                maxc -= cnt;
                take <<= 1;
            }
        }

        for (int t = 0; t <= T; t++) {
            if (dp[t] > answer) answer = dp[t];
        }

        free(verts);
    }

    printf("%lld\n", answer);

    free(p);
    free(tt);
    free(k);
    free(edges);
    free(head);
    free(vis);
    free(queue);
    free(dp);
    free(ndp);

    return 0;
}

import java.io.*;
import java.util.*;

public class Main {
    static class Edge {
        int to, cost;
        Edge(int to, int cost) {
            this.to = to;
            this.cost = cost;
        }
    }

    static final long NEG_INF = Long.MIN_VALUE / 2;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int M = Integer.parseInt(st.nextToken());
        int T = Integer.parseInt(st.nextToken());

        int[] p = new int[N + 1];
        int[] t = new int[N + 1];
        int[] k = new int[N + 1];
        for (int i = 1; i <= N; i++) {
            st = new StringTokenizer(br.readLine());
            p[i] = Integer.parseInt(st.nextToken());
            t[i] = Integer.parseInt(st.nextToken());
            k[i] = Integer.parseInt(st.nextToken());
        }

        List<Edge>[] graph = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) graph[i] = new ArrayList<>();
        for (int i = 0; i < M; i++) {
            st = new StringTokenizer(br.readLine());
            int a = Integer.parseInt(st.nextToken());
            int b = Integer.parseInt(st.nextToken());
            int c = Integer.parseInt(st.nextToken());
            graph[a].add(new Edge(b, c));
        }

        // dp[node][time] = max points achievable ending at node with exactly 'time' used
        long[][] dp = new long[N + 1][T + 1];
        for (int i = 1; i <= N; i++) Arrays.fill(dp[i], NEG_INF);

        // Initialize: start at any node, watch the ad up to k[i] times
        for (int i = 1; i <= N; i++) {
            if (t[i] <= T) {
                long maxPoints = 0;
                for (int cnt = 0; cnt <= k[i]; cnt++) {
                    long points = (long) p[i] * cnt;
                    int time = t[i] * cnt;
                    if (time <= T) {
                        dp[i][time] = Math.max(dp[i][time], points);
                    }
                }
            }
        }

        long answer = 0;
        // Relaxation over time
        for (int time = 0; time <= T; time++) {
            for (int node = 1; node <= N; node++) {
                if (dp[node][time] < 0) continue;
                answer = Math.max(answer, dp[node][time]);
                // Stay and watch more ads at the same node
                if (time + t[node] <= T) {
                    // we can watch up to k[node] times total, but we already watched some
                    // we need to know how many times we've watched already.
                    // Since k[node] is small, we can simulate by trying to add one more
                    // But dp doesn't store count, so we need another approach:
                    // Instead, we'll handle multiple viewings by iterating counts in initialization and transitions.
                }
                // Move to neighbor
                for (Edge e : graph[node]) {
                    int nextTime = time + e.cost;
                    if (nextTime > T) continue;
                    // At the new node, we can watch the ad up to k[e.to] times
                    for (int cnt = 0; cnt <= k[e.to]; cnt++) {
                        long addPoints = (long) p[e.to] * cnt;
                        int totalTime = nextTime + t[e.to] * cnt;
                        if (totalTime > T) break;
                        dp[e.to][totalTime] = Math.max(dp[e.to][totalTime], dp[node][time] + addPoints);
                    }
                }
            }
        }

        System.out.println(answer);
    }
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M, T;
    cin >> N >> M >> T;

    vector<int> p(N), t(N), k(N);
    for (int i = 0; i < N; i++) {
        cin >> p[i] >> t[i] >> k[i];
    }

    vector<vector<pair<int,int>>> adj(N);
    for (int i = 0; i < M; i++) {
        int u, v, w;
        cin >> u >> v >> w;
        u--; v--;
        adj[u].push_back({v, w});
    }

    // dp[node][time] = max points
    vector<vector<int>> dp(N, vector<int>(T+1, -1e9));

    // Initialize: start at any node, can collect its reward
    for (int i = 0; i < N; i++) {
        if (t[i] <= T && k[i] >= 1) {
            dp[i][t[i]] = max(dp[i][t[i]], p[i]);
        }
        // also possibility to start and not collect (points 0)
        dp[i][0] = max(dp[i][0], 0);
    }

    // Relaxation style DP (like Bellman-Ford but for all times)
    for (int _ = 0; _ < N * T; _++) {
        bool updated = false;
        // Try collecting reward again at same node
        for (int u = 0; u < N; u++) {
            for (int time = 0; time <= T; time++) {
                if (dp[u][time] < 0) continue;
                // collect again at u
                if (time + t[u] <= T) {
                    // we can collect multiple times, but limited by k[u]
                    // Since DP doesn't store count, we relax as if we can collect again
                    int val = dp[u][time] + p[u];
                    if (val > dp[u][time + t[u]]) {
                        dp[u][time + t[u]] = val;
                        updated = true;
                    }
                }
            }
        }
        // Move along edges
        for (int u = 0; u < N; u++) {
            for (int time = 0; time <= T; time++) {
                if (dp[u][time] < 0) continue;
                for (auto &[v, w] : adj[u]) {
                    if (time + w > T) continue;
                    // arrive at v, optionally collect its reward
                    // Option 1: don't collect
                    if (dp[u][time] > dp[v][time + w]) {
                        dp[v][time + w] = dp[u][time];
                        updated = true;
                    }
                    // Option 2: collect at v
                    if (time + w + t[v] <= T) {
                        int val = dp[u][time] + p[v];
                        if (val > dp[v][time + w + t[v]]) {
                            dp[v][time + w + t[v]] = val;
                            updated = true;
                        }
                    }
                }
            }
        }
        if (!updated) break;
    }

    int ans = 0;
    for (int i = 0; i < N; i++) {
        for (int time = 0; time <= T; time++) {
            ans = max(ans, dp[i][time]);
        }
    }
    cout << ans << "\n";
    return 0;
}

