    cin >> N >> M >> T;

    vector<int> p(N), t(N), k(N);
    for (int i = 0; i < N; i++) cin >> p[i] >> t[i] >> k[i];

    // Read M links (ignore if travel is free)
    for (int i = 0; i < M; i++) {
        int u, v; cin >> u >> v; // possibly weighted
    }

    // Bounded knapsack
    vector<long long> dp(T + 1, 0);

    for (int i = 0; i < N; i++) {
        // Use binary grouping for bounded knapsack
        vector<pair<int,int>> items; // (weight, value)
        int rem = k[i];
        int mult = 1;
        while (rem > 0) {
            int cnt = min(mult, rem);
            items.push_back({cnt * t[i], cnt * p[i]});
            rem -= cnt;
            mult *= 2;
        }
        for (auto [w, v] : items) {
            for (int j = T; j >= w; j--) {
                dp[j] = max(dp[j], dp[j - w] + v);
            }
        }
    }

    cout << *max_element(dp.begin(), dp.end()) << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll NEG = -(1LL << 60);

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M, T;
    cin >> N >> M >> T;

    vector<int> p(N), tt(N), k(N);
    for (int i = 0; i < N; ++i) cin >> p[i] >> tt[i] >> k[i];

    vector<vector<int>> g(N);
    for (int i = 0; i < M; ++i) {
        int a, b;
        cin >> a >> b;
        --a; --b;
        g[a].push_back(b);
        g[b].push_back(a);
    }

    // dp[time][v][mask]:
    // maximum points after exactly `time` seconds,
    // currently at website v,
    // and among websites, mask indicates which ads have already been watched
    // since the last movement.
    //
    // Because after each movement, only the current vertex matters for further
    // watching, but to model the "cannot watch same ad more than once before using any link"
    // together with per-website total limit k_i, we expand each website i into
    // k_i copies of possible watches:
    //
    // Equivalent simpler interpretation:
    // each time we are at vertex i, before moving again we may watch its ad at most once.
    // Since moving resets this restriction, total watches at i are at most k_i.
    //
    // Then state only needs how many times each ad has been watched globally.
    //
    // However N can be larger, so full multidimensional DP is impossible.
    // Observe that movement costs no time, and start/end anywhere. Therefore only
    // connectivity matters: within a connected component, we may move freely between
    // websites at no time cost, and between different components impossible.
    //
    // Thus for each connected component, the problem becomes:
    // choose x_i (0 <= x_i <= k_i) for vertices in the component
    // maximizing sum x_i * p_i subject to sum x_i * t_i <= T.
    // Answer is the best over all components, since we can start/end anywhere but
    // cannot switch components.
    //
    // So solve bounded knapsack independently on each connected component.

    vector<int> comp(N, -1);
    vector<vector<int>> comps;
    for (int i = 0; i < N; ++i) if (comp[i] == -1) {
        queue<int> q;
        q.push(i);
        comp[i] = (int)comps.size();
        comps.push_back({});
        while (!q.empty()) {
            int v = q.front(); q.pop();
            comps.back().push_back(v);
            for (int to : g[v]) {
                if (comp[to] == -1) {
                    comp[to] = comp[i];
                    q.push(to);
                }
            }
        }
    }

    ll ans = 0;

    for (auto &vertices : comps) {
        vector<ll> dp(T + 1, NEG);
        dp[0] = 0;

        for (int v : vertices) {
            int cnt = k[v];
            int cost = tt[v];
            int val = p[v];

            // binary splitting for bounded knapsack
            int take = 1;
            while (cnt > 0) {
                int use = min(take, cnt);
                int w = use * cost;
                ll gain = 1LL * use * val;
                for (int tm = T; tm >= w; --tm) {
                    if (dp[tm - w] != NEG) {
                        dp[tm] = max(dp[tm], dp[tm - w] + gain);
                    }
                }
                cnt -= use;
                take <<= 1;
            }
        }

        for (int tm = 0; tm <= T; ++tm) ans = max(ans, dp[tm]);
    }

    cout << ans << '\n';
    return 0;
}
